export const AGENT_REGISTRY = [{"name": "ProfileAgent", "module": "coach", "role": "Reads the resume and extracts a factual, structured candidate profile.", "tier": "smart", "prompt_version": "v1", "receives": "Resume text", "decides": "Which skills, roles, achievements and numbers the resume actually supports", "passes_to": "FitAgent, StoryMinerAgent, QuestionPlannerAgent"}, {"name": "JobAnalystAgent", "module": "coach", "role": "Reads the job description and works out what the employer needs and what interviews will probe.", "tier": "smart", "prompt_version": "v1", "receives": "Job description text", "decides": "Must-have vs nice-to-have skills, seniority, and 4-8 weighted competencies", "passes_to": "FitAgent, StoryMinerAgent, QuestionPlannerAgent, EvaluatorAgent"}, {"name": "FitAgent", "module": "coach", "role": "Compares the candidate with the role: strengths with evidence, honest gaps, talking points.", "tier": "smart", "prompt_version": "v1", "receives": "CandidateProfile + JobAnalysis", "decides": "Match score, which requirements are evidenced, which are gaps and how to address them honestly", "passes_to": "QuestionPlannerAgent (gaps become questions), the Prep overview"}, {"name": "StoryMinerAgent", "module": "coach", "role": "Drafts STAR stories from the candidate's real experience, mapped to the job's competencies.", "tier": "smart", "prompt_version": "v1", "receives": "CandidateProfile + JobAnalysis", "decides": "Which experiences make the strongest stories and which details the candidate still needs to fill in", "passes_to": "Story bank (editable), practice prep panel, EvaluatorAgent context"}, {"name": "QuestionPlannerAgent", "module": "coach", "role": "Builds the tailored question bank: what this interviewer is likely to ask this candidate.", "tier": "smart", "prompt_version": "v1", "receives": "CandidateProfile + JobAnalysis + FitAnalysis (+ existing questions to avoid repeats)", "decides": "Which questions to ask, their category, competency, difficulty and what a strong answer includes", "passes_to": "Question bank -> session question selection (spaced repetition) -> InterviewerAgent"}, {"name": "HintAgent", "module": "coach", "role": "Speaking coach during PRACTICE answers: brief nudges on structure and clarity, never content.", "tier": "fast", "prompt_version": "v1", "receives": "The practice question and the partial transcript of the answer so far", "decides": "Whether to show 0-2 short nudges (e.g. 'name your role', 'quantify the result')", "passes_to": "Live hints panel (merged with rule-based delivery/time hints)"}, {"name": "EvaluatorAgent", "module": "coach", "role": "Scores one practice answer against a rubric and explains how to improve it.", "tier": "smart", "prompt_version": "v2", "receives": "Question, competency, the transcript of the answer, measured delivery metrics, role context", "decides": "Scores on 5-6 dimensions, overall score, evidence quotes, specific improvements", "passes_to": "Critic/calibration step -> skill memory -> InterviewerAgent context -> CoachAgent"}, {"name": "InterviewerAgent", "module": "coach", "role": "Plays the interviewer: decides whether to probe with a follow-up or move to the next question.", "tier": "smart", "prompt_version": "v1", "receives": "The question, the candidate's answer, delivery metrics, persona, follow-ups used so far", "decides": "Follow up (and with what question) or move on", "passes_to": "Session controller -> next turn (follow-up or next planned question)"}, {"name": "CoachAgent", "module": "coach", "role": "Writes the end-of-session report and drills, focused on the weakest competencies.", "tier": "smart", "prompt_version": "v1", "receives": "All turns of the session with evaluations, competency score changes", "decides": "Headline, top strengths/improvements, 2-4 drills, what to practice next", "passes_to": "Session report page; next_focus guides the next session's question selection"}, {"name": "ChunkNotesAgent", "module": "notes", "role": "Reads one part of a long transcript and extracts key points, decisions, actions and questions.", "tier": "smart", "prompt_version": "v1", "receives": "A ~9,000-character slice of the transcript (with segment ids)", "decides": "What in this slice matters, with segment references", "passes_to": "NoteEnhancerAgent (reduce step)"}, {"name": "NoteEnhancerAgent", "module": "notes", "role": "Writes the final notes: your own notes are the skeleton; transcript details are added and cited.", "tier": "smart", "prompt_version": "v2", "receives": "Your typed notes + the transcript (or per-part notes for long meetings) + the meeting template", "decides": "Structure, summary, which details to add, decisions, action items, open questions", "passes_to": "Meeting notes page, search index, recipes, interview-debrief -> practice bank"}, {"name": "RecapAgent", "module": "notes", "role": "'Catch me up' during a live meeting: summarises only what was said in the last few minutes.", "tier": "fast", "prompt_version": "v1", "receives": "Transcript of the last N minutes", "decides": "The 3-6 points worth knowing, decisions so far, open questions", "passes_to": "Live meeting sidebar"}, {"name": "MeetingQAAgent", "module": "notes", "role": "Answers questions about saved meetings using only retrieved transcript excerpts, with citations.", "tier": "smart", "prompt_version": "v1", "receives": "Your question + the most relevant transcript excerpts (keyword + semantic retrieval)", "decides": "The answer, which excerpts support it, or that it isn't there", "passes_to": "Ask panel (citations jump to the transcript)"}, {"name": "RecipeAgent", "module": "notes", "role": "Turns saved notes into a ready-to-send draft (follow-up email, team summary, to-do list).", "tier": "smart", "prompt_version": "v1", "receives": "The enhanced notes + the chosen recipe", "decides": "The wording of the draft", "passes_to": "Drafts panel (copy to clipboard)"}];
