export const GOLDEN = [{"id": "strong_star_metrics", "question": "Tell me about a time you took ownership of a problem that wasn't strictly yours.", "category": "behavioral", "competency": "Ownership", "answer": "At my last company our checkout page had a 4% error rate that nobody owned because it sat between the payments and web teams. I was a backend engineer on web, and I decided to take it on. First I pulled two weeks of logs and found that 70% of failures came from a retry bug in our payment client. I wrote a design doc, got sign-off from the payments lead, and shipped a fix with idempotency keys over two sprints. I also set up an alert so we'd catch regressions. As a result the error rate dropped from 4% to 0.3%, which our finance team estimated saved about $40,000 a month. I learned that unowned problems usually need someone to just write down the plan and ask for agreement.", "duration_sec": 95, "expected": [3.8, 5.0]}, {"id": "vague_generic", "question": "Tell me about a time you had to work with a difficult stakeholder.", "category": "behavioral", "competency": "Collaboration", "answer": "I think I'm generally a people person, so I get along with most people. I always try to listen and be respectful, and usually things work out fine. Communication is really important in any team, so I just try to communicate well.", "duration_sec": 25, "expected": [1.0, 2.6]}, {"id": "too_short", "question": "Describe a project you drove end to end. What was the outcome?", "category": "behavioral", "competency": "Ownership", "answer": "I built a dashboard once and people liked it.", "duration_sec": 6, "expected": [1.0, 2.0]}, {"id": "no_result", "question": "Tell me about a time you delivered under a tight deadline.", "category": "behavioral", "competency": "Execution", "answer": "Last year a client moved their launch date up by three weeks, and I was responsible for the reporting module. I sat down with my manager and cut the scope to the four reports they actually needed for launch. I split the work with another developer, I took the data layer, and we did daily check-ins with the client to confirm priorities. I also wrote automated tests for each report so we wouldn't lose time on manual QA at the end.", "duration_sec": 60, "expected": [2.3, 3.8]}, {"id": "we_heavy", "question": "Tell me about the hardest problem you've solved in the last two years.", "category": "behavioral", "competency": "Problem solving", "answer": "We had a big performance issue in our search service. We looked at the profiles and we found that the cache was being invalidated too often. We discussed a few options as a team and we decided to change the cache keys. We rolled it out gradually and we monitored it, and it worked out well for us in the end. Our latency went down a lot.", "duration_sec": 45, "expected": [2.0, 3.6]}, {"id": "off_topic", "question": "Tell me about a time you disagreed with a teammate. How did you resolve it?", "category": "behavioral", "competency": "Collaboration", "answer": "My favourite programming language is Python because it's readable and has a huge ecosystem. I also like TypeScript for frontend work. I try to keep up with new frameworks by reading blogs and doing side projects on weekends.", "duration_sec": 20, "expected": [1.0, 2.5]}, {"id": "strong_technical", "question": "How have you used PostgreSQL in production, and what trade-offs did you make?", "category": "technical", "competency": "Technical depth", "answer": "I ran PostgreSQL as the main store for an order system doing about 2,000 writes per second at peak. The main trade-off was between strict consistency and write throughput. I kept orders in a normalized schema with foreign keys because correctness mattered more than raw speed, but I moved the high-volume event log to a partitioned table by day so vacuum and index maintenance stayed cheap. For reads I added a replica and accepted roughly one second of replication lag for dashboards, while checkout always read from the primary. I chose PgBouncer in transaction mode to cap connections at around 200, which meant giving up session-level features like prepared statements. If I did it again I'd look at logical replication into a separate analytics store earlier, because reporting queries were our biggest source of lock contention.", "duration_sec": 110, "expected": [3.6, 5.0]}, {"id": "weak_technical", "question": "Design a rate limiter for a public API.", "category": "system_design", "competency": "System design", "answer": "I would use a database to store the requests and then check if there are too many. If there are too many I would block them. Maybe use some caching too to make it faster.", "duration_sec": 20, "expected": [1.0, 2.8]}, {"id": "good_motivation", "question": "Why are you interested in this role?", "category": "motivation", "competency": "Communication", "answer": "For the last four years I've built internal data tools, and the part I enjoy most is when analysts stop exporting spreadsheets because the tool answers their question directly. Your team is building the analytics product that your customers use every day, so I'd be doing that same work for thousands of users instead of fifty. I also noticed from your engineering blog that you're moving to a streaming architecture with Kafka, which is exactly what I led at my current company, cutting dashboard latency from hours to under a minute. Long term I want to grow into a tech lead on a product team, and this role sits right on that path.", "duration_sec": 70, "expected": [3.3, 5.0]}, {"id": "rambling_fillers", "question": "Tell me about a time you had to learn something new quickly.", "category": "behavioral", "competency": "Learning agility", "answer": "Um, so, uh, yeah, I mean there was this time, like, where I had to learn, um, Kubernetes, basically, and, uh, it was kind of hard, you know, because, like, I didn't really know it, and, um, I sort of just, like, read stuff and, uh, watched some videos, I guess, and then, um, I kind of figured it out, sort of, and, uh, yeah, it was fine in the end I think.", "duration_sec": 45, "expected": [1.2, 3.0]}, {"id": "failure_learning", "question": "Tell me about a time you failed. What happened and what did you learn?", "category": "behavioral", "competency": "Learning agility", "answer": "In my first year as a team lead I committed to shipping a mobile redesign in six weeks without asking my engineers for estimates. Two weeks before the deadline it was clear we'd miss by a month. I told my director immediately, owned that the estimate was mine, and proposed shipping the three highest-traffic screens first, which we did on time. The full redesign landed four weeks later. Since then I never commit to a date without a team estimate, and I add a checkpoint at the halfway mark. On the next two projects we hit our dates within a week.", "duration_sec": 75, "expected": [3.5, 5.0]}, {"id": "medium_partial", "question": "Tell me about a time you explained something complex to a non-expert audience.", "category": "behavioral", "competency": "Communication", "answer": "I had to explain our machine learning model to the sales team so they could talk to customers about it. I made a short slide deck with a simple analogy about how the model learns from past examples, and I avoided technical terms. I ran a 30-minute session and answered their questions. They said it was helpful and they started using the analogy with customers.", "duration_sec": 50, "expected": [2.6, 4.2]}];
